#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

template <typename scalar_t>
__global__ void rope_kernel(
    scalar_t* __restrict__ q,
    scalar_t* __restrict__ k,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    int64_t rows_q_stride,
    int64_t rows_k_stride,
    int64_t cos_row_stride,
    int64_t sin_row_stride,
    int bs, int sl, int n_qh, int n_kh, int hd, int cos_bs)
{
    int row = blockIdx.x;
    int tid = blockIdx.y * blockDim.x + threadIdx.x;
    int half = hd >> 1;
    int total_q = n_qh * half;
    int total_k = n_kh * half;

    int batch_idx = row / sl;
    int pos = row - batch_idx * sl;
    const float* cos_row = cos + ((cos_bs == 1) ? (int64_t)pos * cos_row_stride
                                                : ((int64_t)batch_idx * sl + pos) * cos_row_stride);
    const float* sin_row = sin + ((cos_bs == 1) ? (int64_t)pos * sin_row_stride
                                                : ((int64_t)batch_idx * sl + pos) * sin_row_stride);

    if (blockIdx.y == 0) {
        for (int idx = tid; idx < total_q; idx += blockDim.x * gridDim.y) {
            int h = idx / half;
            int d = idx - h * half;
            int64_t base = (int64_t)row * rows_q_stride + (int64_t)h * hd;
            float c = cos_row[d];
            float s = sin_row[d];
            float x1 = static_cast<float>(q[base + d]);
            float x2 = static_cast<float>(q[base + d + half]);
            q[base + d] = static_cast<scalar_t>(x1 * c - x2 * s);
            q[base + d + half] = static_cast<scalar_t>(x2 * c + x1 * s);
        }
    } else {
        for (int idx = tid; idx < total_k; idx += blockDim.x * gridDim.y) {
            int h = idx / half;
            int d = idx - h * half;
            int64_t base = (int64_t)row * rows_k_stride + (int64_t)h * hd;
            float c = cos_row[d];
            float s = sin_row[d];
            float x1 = static_cast<float>(k[base + d]);
            float x2 = static_cast<float>(k[base + d + half]);
            k[base + d] = static_cast<scalar_t>(x1 * c - x2 * s);
            k[base + d + half] = static_cast<scalar_t>(x2 * c + x1 * s);
        }
    }
}

std::vector<torch::Tensor> rope_cuda(torch::Tensor q, torch::Tensor k, torch::Tensor cos, torch::Tensor sin) {
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && cos.is_cuda() && sin.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && cos.is_contiguous() && sin.is_contiguous(), "tensors must be contiguous");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && cos.dim() == 3 && sin.dim() == 3, "bad dims");
    int bs = q.size(0);
    int sl = q.size(1);
    int n_qh = q.size(2);
    int hd = q.size(3);
    int n_kh = k.size(2);
    int cos_bs = cos.size(0);
    TORCH_CHECK(k.size(0)==bs && k.size(1)==sl && k.size(3)==hd, "shape mismatch q/k");
    TORCH_CHECK(sin.sizes() == cos.sizes(), "cos/sin mismatch");
    TORCH_CHECK(cos.size(1)==sl && cos.size(2)==hd/2, "bad cos shape");

    auto q_out = q.clone();
    auto k_out = k.clone();

    dim3 block(256);
    dim3 grid(bs * sl, 2);
    auto stream = at::cuda::getDefaultCUDAStream();
    int64_t q_row_stride = q_out.stride(1);
    int64_t k_row_stride = k_out.stride(1);
    int64_t cos_row_stride = cos.stride(1);
    int64_t sin_row_stride = sin.stride(1);

    AT_DISPATCH_FLOATING_TYPES_AND2(at::kHalf, at::kBFloat16, q.scalar_type(), "rope_cuda", [&] {
        rope_kernel<scalar_t><<<grid, block, 0, stream>>>(
            q_out.data_ptr<scalar_t>(),
            k_out.data_ptr<scalar_t>(),
            cos.data_ptr<float>(),
            sin.data_ptr<float>(),
            q_row_stride,
            k_row_stride,
            cos_row_stride,
            sin_row_stride,
            bs, sl, n_qh, n_kh, hd, cos_bs);
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return {q_out, k_out};
}

